"""Independent architecture gates from frozen actual research, no default promotion."""
import json
from pathlib import Path
from tools.m5l_common import write,asset,summary

def read(name):return json.loads(Path('reports/m5l_'+name+'.json').read_text())
def find(rr,**kw):return next(r for r in rr if all(r.get(k)==v for k,v in kw.items()))

def main():
 support=read('sampling_failure_analysis');train=read('vehicle_training');p4=read('p4_feature_quality');shadow=read('online_shadow');gains=[];mobile=[];objs=[]
 for split in ['val','regression','test']:
  baseline=read('baseline_test')if split=='test'else json.loads(Path('reports/m5k_alignment_'+('test'if split=='regression'else split)+'.json').read_text());candidate=read('residual_'+split)
  for seed in [101,102]:
   oldbev=find(baseline['bev'],method='original_p8',seed=seed)
   for mode in ['no_mobile','mobile']:
    name=mode+str(seed);bv=find(candidate['bev'],method=name);details={};protection=[]
    for scope,band in [('all','near'),('actor','near'),('vehicle','10_20'),('vehicle','20_35'),('all','all'),('all','10_20'),('all','20_35')]:
     b=find(baseline['depth'],method='original_p8',scope=scope,band=band);c=find(candidate['depth'],method=name,scope=scope,band=band);details[scope+'_'+band]=dict(n=c['n'],mae=c['expected_mae'],mae_delta=c['expected_mae']-b['expected_mae'],bias=c['bias'],bias_abs_delta=abs(c['bias'])-abs(b['bias']),space1=c['space1'],space_delta=c['space1']-b['space1'],correct_layer=c['correct_layer'])
     if scope=='all':protection.append(c['expected_mae']<=b['expected_mae']*1.05 if band=='near'else abs(c['bias'])<=abs(b['bias'])+(.25 if band=='all'else .5))
     if scope=='actor':protection.append(c['space1']>=b['space1'])
    delta={k:bv[k]-oldbev[k]for k in ['precision','recall1','fpr','actor_detection']};spatial=details['vehicle_20_35']['space_delta']>=.01 and details['vehicle_10_20']['space_delta']>=0;bevgate=delta['precision']>=.01 and delta['recall1']>=.05 and delta['fpr']<=.001
    gains.append(dict(split=split,seed=seed,mode=mode,details=details,bev_delta=delta,near_bias_protection=all(protection),vehicle_space_gain=spatial,bev_gate=bevgate,qualified=all(protection)and spatial and bevgate))
   b=find(candidate['depth'],method='no_mobile'+str(seed),scope='vehicle',band='20_35');c=find(candidate['depth'],method='mobile'+str(seed),scope='vehicle',band='20_35');bb=find(candidate['bev'],method='no_mobile'+str(seed));cb=find(candidate['bev'],method='mobile'+str(seed));mobile.append(dict(split=split,seed=seed,mae_delta=c['expected_mae']-b['expected_mae'],space1_delta=c['space1']-b['space1'],bias_delta=c['bias']-b['bias'],bev_deltas={k:cb[k]-bb[k]for k in ['precision','recall1','fpr']}))
  data=read('objects_'+split)
  for seed in [101,102]:
   r=find(data['aggregate'],seed=seed,scope='all');errors=r['errors'];go=r['valid']>=20 and r['positions']>=3 and r['valid_given_detected']>=.5 and errors['plane_center'].get('p50',1e6)<=.8*errors['dense_expected_center'].get('p50',0)and errors['plane_center'].get('p50',1e6)<=.8*errors['dense_mode_center'].get('p50',0);objs.append(dict(split=split,seed=seed,conditional_research_gate=go,**r))
 write('reports/m5l_vehicle_residual_ablation.json',dict(kind='actual_RTX4090_vehicleonly_2seeds600steps',training=asset('reports/m5l_vehicle_training.json'),comparisons=gains,mobile_condition_increment=mobile,evaluations={s:asset('reports/m5l_residual_'+s+'.json')for s in ['val','regression','test']},m4_replay=asset('reports/m5l_m4_replay_validation.json'),decision='RetainVehicleResearch_Checkpoints_NoDefaultUpgrade',limits='NewM5L vehicleauthorization doesnotchangeM5K gate. B/C sameinitcapacitylossorderbudget; selectedsteps maydiffer onlybyVal. Otherforeground excludedtrain, nearActor evaluation includesothers. RGB/P8features frozen; cannotgeneralize Pedestrian/Cone. No moresteps ornewloss added afterresult.'))
 write('reports/m5l_target_depth_quality.json',dict(kind='actual_GPU_matchedresidual_and_sampling_diagnostics',paths={s:asset('reports/m5l_paths_'+s+'.json')for s in ['val','regression','test']},residual=asset('reports/m5l_vehicle_residual_ablation.json'),p4=asset('reports/m5l_p4_feature_quality.json'),limits='A P8 B interpolationP4 have differentrays; CactualP4Depth nottrained. Vehicle residual sameP8mask. No Oracle2D substituted forrealBEVqualification.'))
 write('reports/m5l_object_2p5d_baseline.json',dict(kind='actual_GPU_RGBcomponents_calibration_flatplane',comparisons=objs,details={s:asset('reports/m5l_objects_'+s+'.json')for s in ['train','val','regression','test']},decision='ConditionalObjectGeometryResearchOnly_ContactNotValidated',limits='All outputs contactunverified conditional hypotheses. Flat ego pose doesnotprove flatlocalroad; GTbottomnearplane strata diagnostic. No objectvolume, meshcenter, drivablefree or safetyclaim. Both bottompoint andAABBcentererrors reported. Occlusion/merged/partialboundaries canbias bottompixel.'))
 adaptive={s:read('adaptive_'+s)for s in ['val','regression','test']};write('reports/m5l_adaptive_mass_diagnostics.json',dict(kind='actual_GPU_fixedROI_samebudget_recomputed',results={s:asset('reports/m5l_adaptive_'+s+'.json')for s in adaptive},attribution={s:v['attribution']for s,v in adaptive.items()},matched={s:v['matched']for s,v in adaptive.items()},decision='NoDefaultUpgrade_FPRMatchedAndRegionControlsRequired',limits='Anewvisibleendpoint andBexistingmasscrossing nonexclusive; newraygeometriccoverage doesnotmean correctlearnedmass. Uniformfrontregion controlsforeknowledge, smallpool maynearlysameasadaptive. LearnedS4 remainsinterpolated.'))
 acceptance=dict(stage='M5-L',status='Partial',engineering='Passed_ExecutedContracts',p4_training='NotRun_SecondClassSupportFailed',vehicle_training='Completed600StepsTwoSeeds',decisions=dict(A_sparse_highres='NoUpgrade_P4SupportAndQualityUnverified',B_dense_residual='VehicleOnlyLearningSignal_RetainFrozenResearch_NoBudgetExpansion',C_object_geometry='ConditionalResearchSignal_ContactAndSlopeUnresolved'),mobile_condition='SmallIncrement_NotStableBEVBenefit',adaptive='ResearchAttribution_NoProductionUpgrade',online_shadow='Stopped_TickTail'if shadow['stopped_for_tick_tail']else'PassedLimitedStaticEngineering',runtime='PartialInherited',occupancy_joint='NoGo',pure_visual_safety='NotValidated',defaults_modified=False,visual_control=False,pretest=asset('reports/m5l_pretest_freeze.json'))
 write('reports/m5l_acceptance.json',acceptance)
 lines=['# M5-L — Sparse Geometry Feasibility & Object-Centric Localization','','**总体Partial；不升级默认Depth/Splat，不启动Occupancy联合训练或视觉控制。**','','## 实际工作与采样失败','','先复用M5-K全部312帧，旧Test仅回归。Train/Val远场行人可靠内部像素335/326、固定P8命中0/0均复现。P4严格射线各9，第二类别覆盖门禁仍失败，未训练P4Depth。实际Mobile浅层S4+语义P8局部特征接口已GPU验证，不把插值当成新视觉信息。','','## Vehicle-only残差','','两个种子，各B/C600步；Val选择Checkpoint，不延长预算。旧M5-K两类别门禁保持原样。','','|集合|seed|方法|20–35m Vehicle MAE|同层1m概率|BEV ΔP/ΔR1/ΔFPR|保护/BEV门禁|','|---|---:|---|---:|---:|---|---|']
 for r in gains:
  v=r['details']['vehicle_20_35'];d=r['bev_delta'];lines.append(f"|{r['split']}|{r['seed']}|{r['mode']}|{v['mae']:.3f}m|{v['space1']:.2%}|{d['precision']:+.2%}/{d['recall1']:+.2%}/{d['fpr']:+.3%}|{r['near_bias_protection']}/{r['bev_gate']}|")
 lines+=['','Mobile条件的独立增量见`m5l_vehicle_residual_ablation.json`；不能把B/C共同收益全归给Mobile。未验证Pedestrian/Cone泛化。','','## 目标级2.5D','','同一RGB候选及底部射线上比较，AABB XY中心只是参考代理；可见底部端点误差另报。不是体素Recall。','','|集合|seed|有效/可见Actor-view|Plane XY中位|Dense Expected XY中位|Dense Mode XY中位|','|---|---:|---:|---:|---:|---:|']
 for r in objs:
  e=r['errors'];lines.append(f"|{r['split']}|{r['seed']}|{r['valid']}/{r['actor_views']}|{e['plane_center'].get('p50',0):.3f}|{e['dense_expected_center'].get('p50',0):.3f}|{e['dense_mode_center'].get('p50',0):.3f}|")
 lines+=['','二值前景不能确认接地或遮挡；输出仅是平面条件假设，可信定位状态仍Unknown。坡道、边缘、合并、分裂和无匹配需单列，不能以条件子集成绩宣称整体通过。','','## 自适应质量归因','','新GT端点覆盖与已有概率质量跨0.2阈值同时统计，并有交集计数，不能相加当成互斥百分比。Val锁定同FPR/Recall工作点，增加同前景矩形预算对照。原公式、48bin和GT隔离未变。详见`m5l_adaptive_mass_diagnostics.json`。','','## 在线Shadow','','实际独立进程2Hz六摄RGB，无CARLA客户端、tick或控制调用。主实验唯一TickOwner运行baseline/shadow/recovery，原时间戳不改、250ms过期拒绝。','',f"是否因tick长尾停止：**{shadow['stopped_for_tick_tail']}**；发出{shadow['sent']}包，输出{shadow['outputs']}，状态{shadow['status_counts']}。",'']
 for r in shadow['phases']:lines.append(f"- {r['phase']} tick P95 {r['tick_ms']['p95']:.2f}ms / Max {r['tick_ms']['max']:.2f}ms；间隔P95 {r['interval_ms']['p95']:.2f}ms。")
 lines+=['','静态传感器工程可运行不代表Oracle驾驶资源争用通过，更不是纯视觉安全认证。','','## 七项回答','','1. P8失败同时受细小轮廓、可靠内部过滤和固定相位影响；真实P4只改善取样机会，现有行人支持仍不足，未验证其Depth空间收益。','2. Vehicle-only残差存在限定学习信号，但背景/近场/场景门禁必须独立看；保留研究Checkpoint，不追加同结构预算。','3. Mobile前景条件只带来小幅概率增量，没有稳定额外BEV优势，不能宣称已解决目标Depth。','4. 额外射线既带来新Oracle表面格，也通过既有格质量累积跨阈值；报告交集与同FPR对照，不把两者做互斥因果拆分。','5. 2.5D在可匹配条件子集有位置研究信号；接地/平面/遮挡可信度仍未解决，不批准通用定位。','6. Shadow结果仅适用于本轮实际静态六摄并发试验，是否触发停止以上述日志为准，不能外推驾驶安全。','7. 下一阶段优先研究可拒绝预测的目标级几何与可靠高分辨率监督；保留Vehicle-only候选供对照，不直接进入正式SparseQuery、Temporal或Occupancy联合训练。','','复现见[实施说明](../docs/M5L_IMPLEMENTATION.md)，预声明见[架构决策](../docs/M5L_ARCHITECTURE_DECISION.md)。所有失败和原始日志保留服务器，Git仅摘要/必要图片/SHA索引。']
 Path('reports/m5l_summary.md').write_text('\n'.join(lines)+'\n')
if __name__=='__main__':main()
